// Interactive Bible Games — question banks + daily rotation.
//
// The banks live in ./games/*.json and are generated by /home/claude/scripts/gen_games.py from the
// bundled KJV text (src/data/kjv_bible.json), book metadata and a hand-curated set
// (scripts/games_curated.py). Every question cites a KJV reference. Validate with
// /home/claude/scripts/validate_games.py after regenerating.
//
// Players get a fresh, date-seeded set every day (see ./games/daily.js): no question repeats
// until its whole pool has been served.
import TRIVIA_RAW from './games/trivia.json';
import WHO_RAW from './games/who.json';
import SCRAMBLE_RAW from './games/scramble.json';
import CHRONO_RAW from './games/chronology.json';
import { dailySelection, dateKey, hash, shuffled, rng, resetLabel, msUntilReset } from './games/daily';

export { dateKey, resetLabel, msUntilReset };

export const GAME_CATEGORIES = [
  { id: 'all', label: 'All Challenges' },
  { id: 'gospels', label: 'Gospels & Jesus' },
  { id: 'old_testament', label: 'Old Testament' },
  { id: 'miracles', label: 'Miracles & Parables' },
  { id: 'prophets', label: 'Prophets & Kings' },
  { id: 'acts', label: 'Acts & Apostles' },
  { id: 'books', label: 'Books of the Bible' },
  { id: 'verses', label: 'Know the verse' },
];
const CAT_LABEL = Object.fromEntries(GAME_CATEGORIES.map((c) => [c.id, c.label]));

// ---------- Banks in the shape the screens use ----------
const toChoice = (x, label) => ({
  id: x.id,
  pool: x.k,
  category: x.c,
  categoryLabel: label || CAT_LABEL[x.c] || 'Bible trivia',
  question: x.q,
  options: x.o,
  correctIndex: x.a,
  reference: x.r,
  explanation: x.x,
});

export const TRIVIA_QUESTIONS = TRIVIA_RAW.map((x) => toChoice(x));
export const WHO_SAID_IT_QUESTIONS = WHO_RAW.map((x) => ({ ...toChoice(x, 'Who said it?'), quote: `“${x.q}”`, question: `“${x.q}”` }));
export const CHRONOLOGY_QUESTIONS = CHRONO_RAW.map((x) => toChoice(x, x.k === 'books' ? 'Order of the books' : 'Bible timeline'));
export const VERSE_SCRAMBLE_DATA = SCRAMBLE_RAW.map((x) => ({
  id: x.id,
  pool: x.k,
  reference: x.r,
  correctOrder: x.w,
  scrambledWords: x.w, // re-shuffled per day by scrambleFor()
  verseText: x.x,
}));

// Canonical game ids (shared by Discover and Learn so stats line up)
export const GAME_IDS = ['trivia', 'who', 'scramble', 'chronology'];
export const GAME_BANKS = {
  trivia: TRIVIA_QUESTIONS,
  who: WHO_SAID_IT_QUESTIONS,
  scramble: VERSE_SCRAMBLE_DATA,
  chronology: CHRONOLOGY_QUESTIONS,
};
// How many of each pool go into one day's session
export const DAILY_MIX = {
  trivia: [['story', 6], ['verse', 4], ['books', 2]],
  who: [['famous', 4], ['more', 8]],
  scramble: [['famous', 4], ['more', 4]],
  chronology: [['events', 7], ['books', 5]],
};
export const DAILY_SIZE = Object.fromEntries(Object.entries(DAILY_MIX).map(([g, m]) => [g, m.reduce((n, [, c]) => n + c, 0)]));
export const GAME_TITLES = { trivia: 'Bible trivia', who: 'Who said it?', scramble: 'Verse scramble', chronology: 'Bible timeline' };

// Shuffle a verse's words for the day (never returns the correct order)
function scrambleFor(v, seed) {
  let w = shuffled(v.correctOrder, seed);
  if (w.join(' ') === v.correctOrder.join(' ')) w = w.slice(1).concat(w.slice(0, 1));
  return { ...v, scrambledWords: w };
}

// Turn a scramble round into a 4-choice question ("pick the correct order") for quick play.
export function scrambleAsChoice(v, seed = hash(v.id)) {
  const right = v.correctOrder.join(' ');
  const r = rng(seed);
  const n = v.correctOrder.length;
  const variants = new Set();
  let guard = 0;
  while (variants.size < 3 && guard < 60) {
    guard += 1;
    const a = v.correctOrder.slice();
    const kind = guard % 3;
    if (kind === 0) { const i = Math.floor(r() * (n - 1)); [a[i], a[i + 1]] = [a[i + 1], a[i]]; }
    else if (kind === 1) { const i = Math.floor(r() * n); let j = Math.floor(r() * n); if (j === i) j = (i + 2) % n; [a[i], a[j]] = [a[j], a[i]]; }
    else { const k = 1 + Math.floor(r() * (n - 1)); a.push(...a.splice(0, k)); }
    const s = a.join(' ');
    if (s !== right) variants.add(s);
  }
  const options = shuffled([right, ...Array.from(variants).slice(0, 3)], seed ^ 0x9e3779b9);
  return {
    id: v.id,
    categoryLabel: 'Verse scramble',
    question: `Which is the correct order of ${v.reference}?`,
    options,
    correctIndex: options.indexOf(right),
    reference: v.reference,
    explanation: v.verseText,
  };
}

// Today's questions for a game (deterministic for the local date).
export function dailyQuestions(gameId, date = new Date()) {
  const bank = GAME_BANKS[gameId] || TRIVIA_QUESTIONS;
  const mix = DAILY_MIX[gameId] || DAILY_MIX.trivia;
  if (gameId === 'scramble') {
    const day = dateKey(date);
    return dailySelection('scramble', bank, mix, date, { shuffleChoices: false }).map((v) => scrambleFor(v, hash(`${v.id}@${day}`)));
  }
  return dailySelection(gameId, bank, mix, date);
}

